def count_paths_of_length(n, edges, s, t, L):
    adj=[[] for _ in range(n)]
    indeg=[0]*n
    for (u,v) in edges:
        adj[u].append(v)
        indeg[v]+=1
    from collections import deque
    q=deque([i for i in range(n) if indeg[i]==0])
    topo=[]
    while q:
        u=q.pop()
        topo.append(u)
        for w in adj[u]:
            indeg[w]-=1
            if indeg[w]==0:
                q.append(w)
    dp=[[0]*(L+1) for _ in range(n)]
    dp[t][0]=1
    for l in range(1,L+1):
        for v in range(n):
            for w in adj[v]:
                dp[v][l]+=dp[w][l-1]
    return dp[s][L]
Изменить логику dp. Определим dp[v][l] как число путей длины l от s до v. Идём по порядку в прямом направлении, от s к t, чтобы правильно аккумулировать значения.

def max_plateaus_with_sum_limit(grid, T):
    n=len(grid)
    m=len(grid[0])
    INF=-1
    dp=[ [[INF]*(T+1) for _ in range(m)] for __ in range(n)]
    dp[0][0][grid[0][0]] = 1
    for i in range(n):
        for j in range(m):
            for s in range(T+1):
                if dp[i][j][s]==INF:
                    continue
                val=dp[i][j][s]
                if i+1<n:
                    ns=s+grid[i+1][j]
                    if ns<=T:
                        if grid[i+1][j]==grid[i][j]:
                            dp[i+1][j][ns]=max(dp[i+1][j][ns],val)
                        else:
                            dp[i+1][j][ns]=max(dp[i+1][j][ns],val+1)
                if j+1<m:
                    ns=s+grid[i][j+1]
                    if ns<=T:
                        if grid[i][j+1]==grid[i][j]:
                            dp[i][j+1][ns]=max(dp[i][j+1][ns],val)
                        else:
                            dp[i][j+1][ns]=max(dp[i][j+1][ns],val+1)
    ans=max(dp[n-1][m-1])
    return ans
Изменить код так, чтобы уменьшить количество памяти.

def min_substring_with_k_distinct_vowels(s, k):
    vowels=set('aeiou')
    n=len(s)
    left=0
    count={}
    ans=float('inf')
    distinct=0
    for right in range(n):
        c=s[right]
        if c in vowels:
            count[c]=count.get(c,0)+1
            if count[c]==1:
                distinct+=1
        if distinct>=k:
            ans=min(ans,right-left+1)
            left+=1
    return ans if ans!=float('inf') else -1
