def count_triplets(arr):
    n = len(arr)
    count = 0
    for i in range(n - 2):
        for j in range(i + 1, n - 1):
            for k in range(j + 1, n):
                if arr[i] < arr[j] < arr[k] and (arr[k] - arr[i] <= 10):
                    count += 1
    return count

