def can_partition(arr):
    total = sum(arr)
    if total % 2 != 0:
        return False
    half = total//2
    dp = [False]*(half+1)
    dp[0] = True
    for num in arr:
        for s in range(half+1):
            if dp[s]:
                dp[s+num] = True  
    return dp[half]
