    static void Main()
    {
        int[] nums = { -2, 1, -3, 4, -1, 2, 1, -5, 4 };
        Console.WriteLine(MaxSubArrayRecursive(nums, 0, nums.Length - 1));
    }

    static int MaxSubArrayRecursive(int[] nums, int left, int right)
    {
        if (left == right)
            return nums[left];

        int mid = (left + right) / 2;

        int leftMax = MaxSubArrayRecursive(nums, left, mid);
        int rightMax = MaxSubArrayRecursive(nums, mid + 1, right);

        int crossMax = MaxCrossingSum(nums, left, mid, right);

        return Math.Max(leftMax, Math.Max(rightMax, crossMax));
    }

    static int MaxCrossingSum(int[] nums, int left, int mid, int right)
    {
        int sum = 0;
        int leftSum = int.MinValue;

        for (int i = mid; i >= left; i--)
        {
            sum += nums[i];
            leftSum = Math.Max(leftSum, sum);
        }

        sum = 0;
        int rightSum = int.MinValue;

        for (int i = mid + 1; i <= right; i++)
        {
            sum += nums[i];
            rightSum = Math.Max(rightSum, sum);
        }

        return leftSum + rightSum;
    }
}

