class AccessControl {
    constructor() {
        this.roles = new Map();
    }

    addRole(role, permissions) {
        if (!Array.isArray(permissions)) {
            throw new Error("Permissions must be an array.");
        }
        this.roles.set(role, new Set(permissions));
