using System;
using System.Drawing;
using System.Windows.Forms;

public class Spiral : Form
{
    private const int scale = 2;

    public Spiral()
    {
        Size = new Size(800, 800);
    }

    protected override void OnPaint(PaintEventArgs e)
    {
        Graphics g = e.Graphics;
        Pen pen = new Pen(Color.Blue, 2);

        g.TranslateTransform(ClientSize.Width / 2, ClientSize.Height / 2);
        g.SmoothingMode = System.Drawing.Drawing2D.SmoothingMode.AntiAlias;

        DrawSpiral(g, pen, 1, 2, 0, 0, 0, 10);
    }

    private void DrawSpiral(Graphics g, Pen pen, int a, int b, int x, int y, int direction, int depth)
    {
        if (depth == 0) return;

        g.DrawRectangle(pen, x, y, a * scale, a * scale);

        switch (direction % 4)
        {
            case 0:
                g.DrawArc(pen, x, y, a * 2 * scale, a * 2 * scale, 180, 90);
                x += a * scale;
                break;
            case 1:
                g.DrawArc(pen, x - a * scale, y, a * 2 * scale, a * 2 * scale, 270, 90);
                x -= (b - a) * scale;
                y += a * scale;
                break;
            case 2:
                g.DrawArc(pen, x - a * scale, y - a * scale, a * 2 * scale, a * 2 * scale, 0, 90);
                x -= b * scale;
                y -= (b - a) * scale;
                break;
            case 3:
                g.DrawArc(pen, x, y - a * scale, a * 2 * scale, a * 2 * scale, 90, 90);
                y -= b * scale;
                break;
        }

        DrawSpiral(g, pen, b, a + b, x, y, direction + 1, depth - 1);
    }

    [STAThread]
    public static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new Spiral());
    }
}

