public class Tetris : Form
{
    private System.Windows.Forms.Timer timer;
    private int[,] board;
    private int boardWidth = 10;
    private int boardHeight = 20;
    private int blockSize = 30;
    private int currentPiece;
    private int currentRotation;
    private int currentX;
    private int currentY;

    private static readonly int[][][] pieces = new int[][][]
    {
        new int[][]{new int[]{ 1, 1, 1, 1 }}, // I

        new int[][]{new int[]{ 1, 1, 1 },
                    new int[]{ 0, 1, 0 }},    // T

        new int[][]{new int[]{ 1, 1 },
                    new int[]{ 1, 1 } },      // O

        new int[][]{new int[]{ 0, 1, 1 },
                    new int[]{ 1, 1, 0 } },   // S

        new int[][]{new int[]{ 1, 1, 0 },
                    new int[]{ 0, 1, 1 } },   // Z

        new int[][]{new int[]{ 1, 0, 0 },
                    new int[]{ 1, 1, 1 } },    // L

        new int[][]{new int[]{ 0, 0, 1 },
                    new int[]{ 1, 1, 1 } }     // J
    };

    public Tetris()
    {
        Width = boardWidth * blockSize + 16;
        Height = boardHeight * blockSize + 39;
        DoubleBuffered = true;

        board = new int[boardWidth, boardHeight];
        timer = new System.Windows.Forms.Timer();
        timer.Interval = 500;
        timer.Tick += Timer_Tick;
        timer.Start();

        KeyDown += Tetris_KeyDown;
        NewPiece();
        FillPiece(1);
    }

    private void Timer_Tick(object? sender, EventArgs e)
    {
        if (!MovePiece(0, 1))
        {
            NewPiece();

            if (!IsValidPosition(currentPiece, currentRotation, currentX, currentY))
            {
                timer.Stop();
                MessageBox.Show("Game Over!");
                return;
            }

            FillPiece(1);
        }

        Invalidate();
    }

    private void NewPiece()
    {
        Random rand = new Random();
        currentPiece = rand.Next(pieces.Length);
        currentRotation = 0;
        currentX = (boardWidth - pieces[currentPiece][0].Length) / 2;
        currentY = 0;
    }

    private bool MovePiece(int dx, int dy)
    {
        FillPiece(0);
        if (IsValidPosition(currentPiece, currentRotation, currentX + dx, currentY + dy))
        {
            currentX += dx;
            currentY += dy;

            FillPiece(1);
            return true;
        }

        FillPiece(1);
        return false;
    }

    private void FillPiece(int check)
    {
        for (int y = 0; y < pieces[currentPiece].GetLength(0); y++)
        {
            for (int x = 0; x < pieces[currentPiece][y].GetLength(0); x++)
            {
                if (pieces[currentPiece][y][x] == 1)
                {
                    board[currentX + x, currentY + y] = check;
                }
            }
        }
    }

    private bool IsValidPosition(int piece, int rotation, int x, int y)
    {
        for (int i = 0; i < pieces[piece].Length; i++)
        {
            for (int j = 0; j < pieces[piece][i].Length; j++)
            {
                if (pieces[piece][i][j] == 1)
                {
                    int newX = x + j;
                    int newY = y + i;
                    if (newX < 0 || newX >= boardWidth || newY < 0 || newY >= boardHeight || board[newX, newY] != 0)
                    {
                        return false;
                    }
                }
            }
        }
        return true;
    }
    protected override void OnPaint(PaintEventArgs e)
    {
        Graphics g = e.Graphics;

        for (int x = 0; x < boardWidth; x++)
        {
            for (int y = 0; y < boardHeight; y++)
            {
                g.FillRectangle(new SolidBrush(board[x, y] != 0 ? Color.Red : Color.White), x * blockSize, y * blockSize, blockSize, blockSize);
                g.DrawRectangle(Pens.Black, x * blockSize, y * blockSize, blockSize, blockSize);
            }
        }
    }

    private void Tetris_KeyDown(object? sender, KeyEventArgs e)
    {
        switch (e.KeyCode)
        {
            case Keys.Left:
                MovePiece(-1, 0);
                break;
            case Keys.Right:
                MovePiece(1, 0);
                break;
            case Keys.Down:
                MovePiece(0, 1);
                break;
        }
        Invalidate();
    }

    [STAThread]
    public static void Main()
    {
        Application.EnableVisualStyles();
        Application.SetCompatibleTextRenderingDefault(false);
        Application.Run(new Tetris());
    }
}

