using Timer = System.Windows.Forms.Timer;

public class RunnerGame : Form
{
    private Timer gameTimer;
    private int playerX = 50;
    private int playerY = 200;
    private int gravity = 1;
    private bool isJumping = false;
    private int jumpSpeed = 15;
    private int score = 0;
    private int speed = 5;

    private List<Rectangle> platforms = new List<Rectangle>();

    public RunnerGame()
    {
        this.DoubleBuffered = true;
        this.Width = 800;
        this.Height = 400;
        this.Text = "Runner Game";

        // Создаем платформы
        platforms.Add(new Rectangle(0, 300, 200, 20));
        platforms.Add(new Rectangle(250, 250, 200, 20));
        platforms.Add(new Rectangle(500, 200, 200, 20));
        platforms.Add(new Rectangle(750, 150, 200, 20));

        gameTimer = new Timer();
        gameTimer.Interval = 20; // 50 FPS
        gameTimer.Tick += new EventHandler(GameLoop);
        gameTimer.Start();

        this.KeyDown += new KeyEventHandler(OnKeyDown);
        this.Paint += new PaintEventHandler(OnPaint);
    }

    private void GameLoop(object sender, EventArgs e)
    {
        for (int i = 0; i < platforms.Count; i++)
        {
            platforms[i] = new Rectangle(platforms[i].X - speed, platforms[i].Y, platforms[i].Width, platforms[i].Height);
        }

        if (platforms[0].X + platforms[0].Width < 0)
        {
            platforms.RemoveAt(0); 

            Random rand = new Random();
            int newY = rand.Next(150, 300);
            platforms.Add(new Rectangle(800, newY, 200, 20));
        }

        if (isJumping)
        {
            playerY -= jumpSpeed;
            jumpSpeed -= gravity;

            // Проверка на приземление
            if (jumpSpeed < 0)
            {
                foreach (var platform in platforms)
                {
                    if (playerX + 50 > platform.X && playerX < platform.X + platform.Width && playerY + 50 >= platform.Y && playerY + 50 <= platform.Y + jumpSpeed)
                    {
                        playerY = platform.Y - 50;
                        isJumping = false;
                        jumpSpeed = 15;
                        break;
                    }
                }
            }
        }
        else
        {
            // Проверка на падение
            bool onPlatform = false;
            foreach (var platform in platforms)
            {
                if (playerX + 50 > platform.X && playerX < platform.X + platform.Width && playerY + 50 >= platform.Y)
                {
                    playerY = platform.Y - 50;
                    onPlatform = true;
                    break;
                }
            }

            if (!onPlatform)
            {
                playerY += gravity; // Игрок падает
            }
        }

        score++;
        this.Invalidate(); // Перерисовать форму
    }

    private void OnKeyDown(object sender, KeyEventArgs e)
    {
        if (e.KeyCode == Keys.Space && !isJumping)
        {
            isJumping = true;
        }
    }

    private void OnPaint(object sender, PaintEventArgs e)
    {
        Graphics g = e.Graphics;
        g.Clear(Color.CornflowerBlue);

        foreach (var platform in platforms)
        {
            g.FillRectangle(Brushes.Green, platform);
        }

        g.FillRectangle(Brushes.Red, playerX, playerY, 50, 50);

        g.DrawString("Score: " + score, new Font("Arial", 16), Brushes.White, 10, 10);
    }

    [STAThread]
    public static void Main()
    {
        Application.EnableVisualStyles();
        Application.Run(new RunnerGame());
    }
}

